    labels:['Depan','Kanan','Belakang','Kiri','Atas','Bawah'],views:['Segi empat tepat \xB7 6 \xD7 4','Segi empat tepat \xB7 6 \xD7 4','Segi empat tepat \xB7 6 \xD7 3','Segi empat tepat \xB7 6 \xD7 3','Segi empat tepat \xB7 4 \xD7 3','Segi empat tepat \xB7 4 \xD7 3'],
