 if(shape==='cuboid'){values=[d.p*d.t,d.l*d.t,d.p*d.t,d.l*d.t,d.p*d.l,d.p*d.l];names=['Depan: p \xD7 t','Kanan: l \xD7 t','Belakang: p \xD7 t','Kiri: l \xD7 t','Atas: p \xD7 l','Bawah: p \xD7 l'];}
 if(shape==='pyramid'){values=[d.a*d.a,...Array(4).fill(d.a*m.slant/2)];names=['Tapak: a\xB2','Segi tiga depan','Segi tiga kanan','Segi tiga belakang','Segi tiga kiri'];}
