 const mesh=[];for(let n=0;n<count;n++){const y=Math.floor(n/(p*l)),z=Math.floor(n/p)%l,x=n%p;mesh.push(...labSolidMesh('cube',{a:1},[x-(p-1)/2,y,z-(l-1)/2],n*6,FACE_COLORS[y%6]));}
